import React from 'react';
import './TruckBookingPage.css'; 
const TruckBookingPage = () => {
  return (
    <div className="truck-booking-container">
      {/* Background Section */}
      <div className="hero-section">
        <h1>Reliable Online Mini Truck Booking in Yamunanagar</h1>
        
        {/* Floating Form Bar */}
        <div className="booking-bar">
          <input type="text" placeholder="Pickup Address" />
          <input type="text" placeholder="Drop Address" />
          <input type="text" placeholder="Name" />
          <input type="tel" placeholder="Phone Number" />
          <button className="fare-btn">Get Fare Estimate</button>
        </div>
      </div>

      {/* Vehicle Options */}
      <div className="vehicle-options">
        <h3>Book Mini Trucks</h3>
        <div className="vehicle-grid">
          <div className="v-card">
            <img src="tata-ace.png" alt="Tata Ace" />
            <h4>Tata Ace</h4>
            <p>750kg Capacity</p>
          </div>
          {/* Baaki cards yahan aayenge */}
        </div>
      </div>
    </div>
  );
};

// Sabse important line jo missing thi:
export default TruckBookingPage;
